import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { asString, useSearchParam } from '../../url/useSearchParam';
import { peopleKey, type Person } from './usePeople';

// Puts the person on hold, or takes them off hold when already held. While held their OPEN claims
// count in no live total; their SETTLED claims still do. A refusal shows the person's error.
export function HoldControl({ personId, held }: { personId: string; held: boolean }) {
  const [sheet] = useSearchParam('sheet', asString);
  const [user] = useSearchParam('user', asString);
  const queryClient = useQueryClient();
  const once = useSubmitOnce();

  const hold = useMutation({
    mutationFn: () =>
      postJson<Person>(`/api/sheets/${encodeURIComponent(sheet)}/people/${encodeURIComponent(personId)}/hold`, {
        user,
      }),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: peopleKey(sheet) }),
  });

  return (
    <>
      <button
        type="button"
        data-testid="person-hold-toggle"
        onClick={() => {
          hold.reset();
          once(() => hold.mutateAsync());
        }}
      >
        {held ? 'Release' : 'Hold'}
      </button>
      {hold.isError && (
        <span data-testid="person-error" role="alert">
          {' '}
          The person could not be put on or taken off hold.
        </span>
      )}
    </>
  );
}
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { asString, useSearchParam } from '../../url/useSearchParam';
import { peopleKey, type Person } from './usePeople';

// Retires the person from a date (blank takes the sheet's today): from then on no claim of theirs
// may be dated after it, and the list leaves them out unless "show retired" is on. A refusal shows
// the person's error.
export function RetireControl({ personId }: { personId: string }) {
  const [sheet] = useSearchParam('sheet', asString);
  const [user] = useSearchParam('user', asString);
  const [date, setDate] = useState('');
  const queryClient = useQueryClient();
  const once = useSubmitOnce();

  const retire = useMutation({
    mutationFn: (from: string) =>
      postJson<Person>(`/api/sheets/${encodeURIComponent(sheet)}/people/${encodeURIComponent(personId)}/retire`, {
        date: from,
        user,
      }),
    onSuccess: () => {
      setDate('');
      return queryClient.invalidateQueries({ queryKey: peopleKey(sheet) });
    },
  });

  return (
    <>
      <input
        type="date"
        data-testid="person-retire-date"
        value={date}
        onChange={(e) => {
          setDate(e.target.value);
          retire.reset();
        }}
      />{' '}
      <button
        type="button"
        data-testid="person-retire"
        onClick={() => {
          retire.reset();
          once(() => retire.mutateAsync(date.trim()));
        }}
      >
        Retire
      </button>
      {retire.isError && (
        <span data-testid="person-error" role="alert">
          {' '}
          The person could not be retired.
        </span>
      )}
    </>
  );
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

/** `version` goes up on every save; an editor sends back the version it loaded, so a save over
 *  someone else's newer one is refused. `statementCount` is how many statements were taken;
 *  `statedTotal` is the last one's due-total ("n/a" possible, "" when none) and `statementDate` the
 *  sheet's today when it was taken ("" when none). `retired` is whether a retirement date is set
 *  (retired at once, whatever the date) and `retiredFrom` is that date ("" when none). `held` is
 *  whether the person is on hold: their OPEN claims then count in no live total. `patrons` are the
 *  names of the people they named as patrons, sorted, and `patronIds` those people's ids. `grade`
 *  is the grade in force on the sheet's today when loaded and `grades` every grade recorded. */
export type Person = {
  id: string;
  name: string;
  grade: string;
  version: number;
  statementCount: number;
  statedTotal: string;
  statementDate: string;
  retired: boolean;
  retiredFrom: string;
  held: boolean;
  patrons: string[];
  patronIds: string[];
  grades: GradeFrom[];
};

/** A grade in force from a date (YYYY-MM-DD; "" for the beginning of time). */
export type GradeFrom = { from: string; grade: string };

